	//   Let j = number of b_i that equal x. j >= 1.
	//   For a fixed j, choose which j of the m players have score x: C(m, j).
	//   The remaining m-j players have sum = s-x - j*x = s - (j+1)*x, each >= 0 and <= x-1 (since if any were >= x, max would be > x or we'd have more x's... wait, no, they can be up to x-1 since max is exactly x and we've already counted the j that are x).
	//   Actually, the remaining m-j players must have scores in [0, x-1] and sum to s - (j+1)*x.
	//   Number of such solutions: let T(m-j, s-(j+1)*x, x-1) = number of non-negative solutions to c1+...+c_{m-j} = s-(j+1)*x with each c_i <= x-1.
	//   = sum_{k=0}^{m-j} (-1)^k * C(m-j, k) * C(s-(j+1)*x - k*x + (m-j) - 1, (m-j) - 1)
	//   And for each such state, the contribution is 1/(j+1).

	// So S(x) = [number of states with all b_i < x] + sum_{j=1}^{m} C(m, j) * [number of states with remaining m-j players summing to s-(j+1)*x, each <= x-1] * (1/(j+1))

	// Let's define a helper function to compute the number of non-negative solutions to y1+...+yn = N with each y_i <= U.
	// countSolutions(n, N, U) = sum_{j=0}^{n} (-1)^j * C(n, j) * C(N - j*(U+1) + n - 1, n - 1)
	// where C(a, b) = 0 if a < b or a < 0 or b < 0.

	countSolutions := func(n, N, U int) int64 {
		if n == 0 {
			if N == 0 {
				return 1
			}
			return 0
		}
		if N < 0 {
			return 0
		}
		var res int64 = 0
		for j := 0; j <= n; j++ {
			term := N - j*(U+1)
			if term < 0 {
				break
			}
			c := nCr(term+n-1, n-1)
			if j%2 == 0 {
				res = (res + int64(c)) % mod
			} else {
				res = (res - int64(c) + mod) % mod
			}
		}
		return res
	}

	var numerator int64 = 0
	m := p - 1
	for x := r; x <= s; x++ {
		remaining := s - x
		if remaining < 0 {
			break
		}
		// Case 1: all b_i < x, i.e., each b_i <= x-1
		case1 := countSolutions(m, remaining, x-1)
		numerator = (numerator + case1) % mod

		// Case 2: max(b_i) = x
		// j = number of b_i equal to x, j from 1 to m
		for j := 1; j <= m; j++ {
			remSum := remaining - j*x
			if remSum < 0 {
				break
			}
			// Choose j players out of m to have score x
			chooseJ := nCr(m, j)
			// Remaining m-j players sum to remSum, each <= x-1
			remCount := countSolutions(m-j, remSum, x-1)
			// Contribution: chooseJ * remCount * (1/(j+1))
			invJ1 := modInv(int64(j+1))
			term := chooseJ * remCount % mod * invJ1 % mod
			numerator = (numerator + term) % mod
		}
	}

	// Probability = numerator / totalStates
	// Answer = numerator * inv(totalStates) mod mod
	answer := numerator * modInv(totalStates) % mod
	fmt.Println(answer)
}
