	// Total number of states: number of non-negative integer solutions to
	// a1 + a2 + ... + ap = s with a1 >= r
	// Let b1 = a1 - r >= 0, then b1 + a2 + ... + ap = s - r
	// Number of solutions = C((s-r) + p - 1, p - 1) = C(s - r + p - 1, p - 1)

	// We need to compute combinations modulo mod.
	// Since s <= 5000 and p <= 100, the maximum n for combinations is s + p - 1 <= 5100.
	// We can precompute factorials and inverse factorials.

	maxN := s + p // safe upper bound
	fact := make([]int64, maxN+1)
	invFact := make([]int64, maxN+1)

