	for i := maxN - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * int64(i+1) % mod
	}

	// C(n, k) = fact[n] * invFact[k] * invFact[n-k] mod mod
	// Only valid if 0 <= k <= n, else 0
	nCr := func(n, k int) int64 {
		if k < 0 || k > n {
			return 0
		}
		return fact[n] * invFact[k] % mod * invFact[n-k] % mod
