	// Hasan's contribution to the winning probability in that state is 1/m.
	// So we need to compute S = sum over all valid states of (1 / m), where m = number of players with score = a1.
	// Then answer = S / totalStates mod mod.

	// How to compute S?
	// Let a1 = x, where x >= r.
	// For a fixed x, the remaining p-1 players have scores a2, ..., ap such that a2 + ... + ap = s - x, and each ai >= 0.
	// Also, for Hasan to be a top-scorer, we need ai <= x for all i.
	// Let m = number of players (including Hasan) with score exactly x.
	// So among a2, ..., ap, let k = m - 1 be the number of players with score exactly x, and the rest have score < x.
	// 
	// For fixed x and k (0 <= k <= p-1):
	//   Choose k players out of p-1 to have score x: C(p-1, k)
	//   The remaining p-1-k players have scores in [0, x-1], and their sum is (s - x) - k*x = s - x*(k+1).
	//   Let T = s - x*(k+1). We need T >= 0.
	//   Number of non-negative integer solutions to y1 + ... + y_{p-1-k} = T with each yi <= x-1.
	//   This is a bounded composition problem.
	//
	// The number of solutions to y1 + ... + y_m = T with 0 <= yi <= U is:
	//   sum_{j=0}^{floor(T/(U+1))} (-1)^j * C(m, j) * C(T - j*(U+1) + m - 1, m - 1)
	// where m = p-1-k, U = x-1.
	//
	// So for fixed x and k:
	//   count = C(p-1, k) * boundedCount(p-1-k, T, x-1)
	//   where boundedCount(m, T, U) = number of solutions to y1+...+ym = T with 0<=yi<=U.
	//
	// And the contribution to S from this (x, k) is: count * (1/(k+1))
	// because m = k+1 top-scorers, so Hasan's win prob in each such state is 1/(k+1).

	// So S = sum_{x=r}^{s} sum_{k=0}^{p-1} [ C(p-1,k) * boundedCount(p-1-k, s - x*(k+1), x-1) * inv(k+1) ]
	// where boundedCount(m, T, U) = 0 if T < 0 or T > m*U, else the inclusion-exclusion sum.

	// Let's implement boundedCount.
	boundedCount := func(m, T, U int) int64 {
		if T < 0 || m < 0 {
			return 0
		}
		if U < 0 {
			// If U < 0, then no yi can be >= 0 and <= U unless T=0 and m=0
			if T == 0 && m == 0 {
				return 1
			}
			return 0
		}
		if T > m*U {
			return 0
		}
		// Inclusion-exclusion
		// Number of non-negative solutions to y1+...+ym = T with yi <= U
		// = sum_{j=0}^{min(m, floor(T/(U+1)))} (-1)^j * C(m, j) * C(T - j*(U+1) + m - 1, m - 1)
		result := int64(0)
		maxJ := T / (U + 1)
		if maxJ > m {
			maxJ = m
		}
		for j := 0; j <= maxJ; j++ {
			term := nCr(m, j) * nCr(T - j*(U+1)+m-1, m-1) % mod
			if j%2 == 1 {
				result = (result - term + mod) % mod
			} else {
				result = (result + term) % mod
			}
		}
		return result
	}

	S := int64(0)
	for x := r; x <= s; x++ {
		for k := 0; k <= p-1; k++ {
			T := s - x*(k+1)
			if T < 0 {
				break
			}
			m := p - 1 - k
			cnt := boundedCount(m, T, x-1)
			if cnt == 0 {
				continue
			}
			choose := nCr(p-1, k)
			invK1 := modInv(int64(k + 1))
			contrib := choose * cnt % mod * invK1 % mod
			S = (S + contrib) % mod
		}
	}

	// Answer = S / totalStates mod mod
	ans := S * modInv(int64(totalStates)) % mod
	fmt.Println(ans)
}
