func modPow(a, b int64) int64 {
	result := int64(1)
	a %= mod
	for b > 0 {
		if b%2 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		b /= 2
	}
	return result
}

func modInverse(a int64) int64 {
	return modPow(a, mod-2)
}

// C(n, k) mod mod
func comb(n, k int) int64 {
	if k < 0 || k > n {
		return 0
	}
	// Precompute factorials up to n
	// We'll compute on the fly using a helper
	return nCk(n, k)
}

var factCache = map[int][]int64{}

func getFactorials(n int) []int64 {
	if f, ok := factCache[n]; ok {
		return f
	}
	f := make([]int64, n+1)
	f[0] = 1
	for i := 1; i <= n; i++ {
		f[i] = f[i-1] * int64(i) % mod
	}
	factCache[n] = f
	return f
}

func nCk(n, k int) int64 {
	if k < 0 || k > n {
		return 0
	}
	f := getFactorials(n)
	num := f[n]
	den := f[k] * f[n-k] % mod
	return num * modInverse(den) % mod
}

// Number of non-negative integer solutions to x1 + x2 + ... + xm = n is C(n+m-1, m-1)
// Here we need: a1 >= r, a1 + a2 + ... + ap = s
// Let b1 = a1 - r >= 0, then b1 + a2 + ... + ap = s - r
// Number of solutions = C((s-r) + p - 1, p - 1) = C(s - r + p - 1, p - 1)
// But we need to handle the case where s - r < 0, which means 0 solutions.

func main() {
	var p, s, r int
	_, err := fmt.Fscanf(os.Stdin, "%d %d %d", &p, &s, &r)
	if err != nil {
		fmt.Println(0)
		return
	}

	if r > s {
		fmt.Println(0)
		return
	}

	// Total number of valid states: a1 >= r, a_i >= 0, sum = s
	// Let b1 = a1 - r >= 0, then b1 + a2 + ... + ap = s - r
	// Number of non-negative solutions = C((s-r) + p - 1, p - 1)
	// But this is only valid if s - r >= 0.

	totalStates := int64(0)
	if s >= r {
		totalStates = nCk(s-r+p-1, p-1)
	} else {
		fmt.Println(0)
		return
	}

	if totalStates == 0 {
		fmt.Println(0)
		return
	}

	// Now count the number of "winning" outcomes.
	// Hasan wins if:
	// 1. a1 > max(a2, ..., ap) -> he is the unique top scorer
	// 2. a1 == max(a2, ..., ap) and there are k players tied with him (including himself), 
	//    then he wins with probability 1/k.

	// We need to sum over all valid states the probability of winning.
	// For a given state (a1, a2, ..., ap), the probability of Hasan winning is:
	//   1 if a1 > all others
	//   1/k if a1 == max and exactly k players have score a1 (including Hasan)

	// Let's iterate over possible values of a1 from r to s.
	// For a fixed a1 = x (where x >= r and x <= s), the remaining sum is s - x for p-1 players.
	// We need to count, for each such x, the number of ways to assign (a2, ..., ap) such that:
	//   - all a_i >= 0
	//   - sum a_i = s - x
	//   - and compute the winning probability contribution.

	// For fixed x = a1:
	//   Let m = s - x (sum for others)
	//   We need to count tuples (a2,...,ap) with sum m, a_i >= 0.
	//   Among these, let's categorize by the maximum value among a2,...,ap.
	//   Actually, it's easier to think in terms of how many of a2,...,ap are >= x, = x, etc.

	// Alternative approach:
	// For fixed a1 = x:
	//   Case 1: All a_i < x for i >= 2. Then Hasan is unique top scorer. Win prob = 1.
	//   Case 2: Some a_i = x and the rest < x. Let k be the number of players (among a2..ap) with score exactly x.
	//            Then total tied = k + 1 (including Hasan). Win prob = 1/(k+1).
	//   Case 3: Some a_i > x. Then Hasan doesn't win. Win prob = 0.

	// So for fixed x, we need:
	//   A(x) = number of (a2,...,ap) with sum = m, all a_i < x
	//   B(x, k) = number of (a2,...,ap) with sum = m, exactly k of them equal to x, and the rest < x
	//   (Note: if any a_i > x, we don't count it for winning)

	// Actually, we can use inclusion-exclusion or generating functions.

	// Let's define:
	//   F(m, p-1, x) = number of non-negative integer solutions to a2+...+ap = m with each a_i < x
	//   This is the number of solutions where each a_i is in [0, x-1].
	//   Using inclusion-exclusion: 
	//   F = sum_{j=0}^{p-1} (-1)^j * C(p-1, j) * C(m - j*x + p-2, p-2)
	//   where C(n, k) = 0 if n < k or n < 0.

	//   For exactly k of a2..ap equal to x:
	//   Choose which k: C(p-1, k)
	//   The remaining p-1-k players have sum m - k*x, each < x.
	//   So B(x, k) = C(p-1, k) * F(m - k*x, p-1-k, x)
	//   where F(m', n, x) = number of non-negative solutions to n variables summing to m' with each < x.
	//   F(m', n, x) = sum_{j=0}^{n} (-1)^j * C(n, j) * C(m' - j*x + n - 1, n - 1)
	//   (with C(a,b)=0 if a<b or a<0)

	// Let's implement this.

	// Precompute factorials up to max needed: s + p
	maxN := s + p + 10
	_ = getFactorials(maxN)

	winProb := int64(0)

	for x := r; x <= s; x++ {
		m := s - x
		if m < 0 {
			continue
		}

		// For fixed x = a1, remaining sum m for p-1 players.
		// We need to count contributions where no a_i > x.

		// A(x): all a_i < x
		// B(x, k): exactly k a_i = x, rest < x, for k = 0 to p-1

		// Let's compute F(m, n, x) for various n and m.
		// F(m, n, x) = number of non-negative solutions to n variables summing to m, each < x.
		// = sum_{j=0}^{n} (-1)^j * C(n, j) * C(m - j*x + n - 1, n - 1)

		// For k = 0: all < x, contribution = F(m, p-1, x) * 1
		// For k >= 1: exactly k equal to x, rest < x, contribution = C(p-1, k) * F(m - k*x, p-1-k, x) * 1/(k+1)

		// Note: if m - k*x < 0, F = 0.

		// Compute F(m, n, x)
		computeF := func(m, n, x int) int64 {
			if n == 0 {
				if m == 0 {
					return 1
				}
				return 0
			}
			if m < 0 {
				return 0
			}
			result := int64(0)
			for j := 0; j <= n; j++ {
				// (-1)^j * C(n, j) * C(m - j*x + n - 1, n - 1)
				term := nCk(n, j) * nCk(m-j*x+n-1, n-1) % mod
				if j%2 == 1 {
					term = (mod - term) % mod
				}
				result = (result + term) % mod
			}
			return result
		}

		// k = 0
		f0 := computeF(m, p-1, x)
		winProb = (winProb + f0) % mod

		// k = 1 to p-1
		for k := 1; k <= p-1; k++ {
			remaining := m - k*x
			if remaining < 0 {
				break
			}
			// C(p-1, k) * F(remaining, p-1-k, x) * 1/(k+1)
			ck := nCk(p-1, k)
			fk := computeF(remaining, p-1-k, x)
			// Multiply by 1/(k+1)
			inv := modInverse(int64(k+1))
			contrib := ck * fk % mod * inv % mod
			winProb = (winProb + contrib) % mod
		}
	}

	// Probability = winProb / totalStates
	// Report winProb * totalStates^{-1} mod mod
	ans := winProb * modInverse(totalStates) % mod
	fmt.Println(ans)
}
