	}

	nCr := func(n, r int) int64 {
		if r < 0 || r > n {
			return 0
		}
		return fact[n] * invFact[r] % mod * invFact[n-r] % mod
	}

	// H(n, S, M): number of non-negative solutions to y1+...+yn = S with each yi <= M
	H := func(n, S, M int) int64 {
		if S < 0 {
			return 0
		}
		if n == 0 {
			if S == 0 {
				return 1
			}
			return 0
		}
		if M < 0 {
