		}
		// Inclusion-exclusion
		result := int64(0)
		maxJ := S / (M + 1)
		for j := 0; j <= maxJ; j++ {
			term := nCr(n, j)
			remaining := S - j*(M+1)
			if remaining < 0 {
				break
			}
			// Number of non-negative solutions to y1+...+yn = remaining (no upper bound) is C(remaining + n - 1, n - 1)
			ways := nCr(remaining+n-1, n-1)
