	// We can compute H(n, sum, maxVal) using inclusion-exclusion:
	//   H(n, sum, maxVal) = Sum_{j=0}^{floor(sum/(maxVal+1))} (-1)^j * C(n, j) * C(sum - j*(maxVal+1) + n - 1, n - 1)
	//
	// But note: if sum - j*(maxVal+1) < 0, the term is 0.
	//
	// Let's implement this.

	// Precompute C(n, k) for n up to maxN
	// We already have fact and invFact, so nCr is ready.

	// Function to compute H(n, sum, maxVal)
	H := func(n, sum, maxVal int) int64 {
		if n == 0 {
			if sum == 0 {
				return 1
			}
			return 0
		}
		if sum < 0 {
			return 0
		}
		// Inclusion-exclusion
		var res int64 = 0
		for j := 0; j*(maxVal+1) <= sum; j++ {
			term := nCr(n, j) * nCr(sum-j*(maxVal+1)+n-1, n-1) % mod
			if j%2 == 1 {
				res = (res - term + mod) % mod
			} else {
				res = (res + term) % mod
			}
		}
		return res
	}

	var totalWinning int64 = 0

	for x := r; x <= s; x++ {
		remaining := s - x
		if remaining < 0 {
			break
		}

		// A(x): all others < x
		a := H(p-1, remaining, x-1)

		// B(x): max of others == x
		var b int64 = 0
		maxC := p - 1
		if x > 0 {
			if remaining/x < maxC {
				maxC = remaining / x
			}
		} else {
			// x == 0, then remaining must be 0 for any assignment, but max == 0 means all are 0
			// If x == 0 and remaining == 0, then all others are 0, so c = p-1
			// If x == 0 and remaining > 0, impossible
			if remaining == 0 {
				maxC = p - 1
			} else {
				maxC = -1 // no valid c
			}
		}

		for c := 1; c <= maxC; c++ {
			remSum := remaining - c*x
			if remSum < 0 {
				break
			}
			// Choose c players out of p-1 to have score x
			choose := nCr(p-1, c)
			// Remaining p-1-c players have scores <= x-1 and sum to remSum
			h := H(p-1-c, remSum, x-1)
			// Contribution: choose * h / (c+1)
			// We need to multiply by modular inverse of (c+1)
			invC1 := modInv(int64(c + 1))
			term := choose * h % mod * invC1 % mod
			b = (b + term) % mod
		}

		totalWinning = (totalWinning + a + b) % mod
	}

	// The answer is totalWinning * modInv(totalStates) mod mod
	ans := totalWinning * modInv(int64(totalStates)) % mod
	fmt.Println(ans)
}
